// Semver range check: ^ allows minor+patch, ~ allows patch only
function parse(v) { return v.split('-')[0].split('.').map(Number); }
function cmp(a, b) {
  for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] - b[i];
  return 0;
}
// Upper bound (exclusive) for each range kind
function upper(kind, v) {
  const [maj, min, pat] = parse(v);
  if (kind === '~') return [maj, min + 1, 0];
  if (maj > 0) return [maj + 1, 0, 0];      // ^1.4.2 -> <2.0.0
  if (min > 0) return [0, min + 1, 0];      // ^0.4.2 -> <0.5.0
  return [0, 0, pat + 1];
}
function best(range, versions) {
  const kind = range[0], base = range.slice(1), hi = upper(kind, base);
  const ok = versions.filter(v => cmp(parse(v), parse(base)) >= 0 && cmp(parse(v), hi) < 0);
  ok.sort((a, b) => cmp(parse(a), parse(b)));
  return ok[ok.length - 1];   // npm picks the highest match
}
