// A lockfile stores an exact version and a hash of each package's contents
const crypto = require('crypto');
const sha = s => 'sha256-' + crypto.createHash('sha256').update(s).digest('hex').slice(0, 12);

// What the registry served when the lockfile was created
const original = { 'left-pad@1.3.0': 'function pad(){ /* real code */ }' };
const lockfile = {};
for (const k in original) lockfile[k] = sha(original[k]);
console.log('lockfile:', JSON.stringify(lockfile));

// Install step: recompute the hash and compare with the lockfile
function install(name, served) {
  const ok = sha(served) === lockfile[name];
  console.log(name, ok ? 'OK, hash matches' : 'FAIL, content differs from lockfile');
}
install('left-pad@1.3.0', original['left-pad@1.3.0']);              // same bytes
