// Walk static imports depth first; dependencies are emitted before users
function chunkFrom(entry, skip) {
  const out = [], seen = new Set(skip);
  (function visit(f) {
    if (seen.has(f)) return;
    seen.add(f);
    files[f].imports.forEach(visit);
    out.push(f);
  })(entry);
  return out;
}
