// TypeScript says User = { name: string, age: number }, but at runtime
// JSON from the network can be anything. Validate at the edge.
function parseUser(data) {
  if (typeof data !== 'object' || data === null) return { ok: false, error: 'not an object' };
  if (typeof data.name !== 'string') return { ok: false, error: 'name must be string' };
  if (typeof data.age !== 'number') return { ok: false, error: 'age must be number' };
  return { ok: true, value: { name: data.name, age: data.age } };
}
