// Element appears at t=130ms. A fixed sleep guesses; polling waits just enough.
const appearsAt = 130;
const visible = t => t >= appearsAt;

function fixedSleep(ms) {
  // Wait ms once, then check once
  return { passed: visible(ms), time: ms };
}
function pollUntil(intervalMs, timeoutMs) {
  // Re-check on every tick until true or timeout (what web-first assertions do)
  for (let t = 0; t <= timeoutMs; t += intervalMs) {
    if (visible(t)) return { passed: true, time: t };
  }
  return { passed: false, time: timeoutMs };
}
